import{_ as i,o as t,c as a,aa as n}from"./chunks/framework.BAs_AphD.js";const u=JSON.parse('{"title":"Signing and Locking a Day","description":"","frontmatter":{"title":"Signing and Locking a Day","wiki":"en:diary:signing"},"headers":[],"relativePath":"en/diary/signing.md","filePath":"en/diary/signing.md","lastUpdated":1793088561000}'),r={name:"en/diary/signing.md"};function o(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="signing-and-locking-a-day" tabindex="-1">Signing and Locking a Day <a class="header-anchor" href="#signing-and-locking-a-day" aria-label="Permalink to &quot;Signing and Locking a Day&quot;">​</a></h1><p>Buildary can be used so that the Daily Report is printed and signed on paper. In this case, the construction diary is maintained in paper form. This approach is supported and, when authorized persons do not have electronic signing certificates, it can be a practical solution.</p><p>The main purpose of the Buildary application is to maintain the construction diary in electronic form. The conditions under which this is possible are described in the Legislation section. This section also explains terms such as qualified electronic signature and signing certificate.</p><h2 id="requirements-for-an-electronic-signature" tabindex="-1">Requirements for an Electronic Signature <a class="header-anchor" href="#requirements-for-an-electronic-signature" aria-label="Permalink to &quot;Requirements for an Electronic Signature&quot;">​</a></h2><p>Before signing reports from Buildary, make sure that you have a signing certificate available. To operate in production mode, you will need a qualified digital certificate issued by a certification authority.</p><p>If you only want to test working with Buildary and electronic signing, use the Buildary certificate. See <strong><a href="/buildary-help-preview/en/diary/signaturesetting">Signature Method Settings</a></strong>.</p><h2 id="obtaining-a-qualified-certificate" tabindex="-1">Obtaining a Qualified Certificate <a class="header-anchor" href="#obtaining-a-qualified-certificate" aria-label="Permalink to &quot;Obtaining a Qualified Certificate&quot;">​</a></h2><p>In the Czech Republic, the services of three certification authorities can be used. The most widely used is probably PostSignum, operated by Česká pošta (Czech Post). A certificate can therefore be obtained at any Czech Post branch providing Czech POINT services. The procedure for obtaining a certificate is described on their website at <a href="http://www.postsignum.cz/" target="_blank" rel="noreferrer">http://www.postsignum.cz/</a>.</p><p>In 2021, First information systems, s.r.o. became a so-called External Registration Authority of Česká pošta and is therefore authorized to issue qualified PostSignum certificates. We offer this service exclusively as part of in-person training. For more information, contact us at <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you install the certificate in your local Windows machine, you can avoid repeatedly entering the access password when creating a signature.</p></div><h2 id="signing-the-report-and-locking-records-or-a-day" tabindex="-1">Signing the Report and Locking Records or a Day <a class="header-anchor" href="#signing-the-report-and-locking-records-or-a-day" aria-label="Permalink to &quot;Signing the Report and Locking Records or a Day&quot;">​</a></h2><p>The first signature on a Other entry locks the record. Likewise, the first signature on a Daily Report locks the day.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When signing and therefore locking the first Daily Report, make sure that it really is the first day in the diary. Once the first day has been locked, you will no longer be able to add any daily records before that day!!!</p><p>In other words: Data can be entered in any order, but days must always be signed, and therefore locked, sequentially, starting with the first day of the construction diary.</p></div><p>Before signing the Daily Report, all records in the Other entries section must be signed (unless you are their author). If this condition is not met, Buildary will refuse to sign the Daily Report. This behavior is enabled by default. In Diary Settings, you can disable the <strong>Other entries signature check</strong> option, in which case this check will not be performed.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Daily Report must be signed first by the person responsible for maintaining the construction diary, i.e. a person with rights to Regular Records. This allows them to control when the day is actually locked.</p></div><p>Before starting the signing process, you need to configure the <strong><a href="/buildary-help-preview/en/diary/signaturesetting">Signature Method Settings</a></strong>. The actual signing procedure differs depending on the selected signing method and is explained in separate videos.</p><p>If the signature and upload are not completed within the time limit, the temporary lock is removed and users can continue working normally. An upload submitted after the time limit has expired will be rejected.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The signing time limit is configured at the diary level. A setting of around 5 minutes is recommended, but users can adjust the limit according to their needs.</p></div>',18)])])}const p=i(r,[["render",o]]);export{u as __pageData,p as default};
